%[text] # Simulating elevation profile using Road Grade Profile block
model_name = "HarnessModel_ElevationProfile";
load_system(model_name)
%%
%[text] Simulation conditions;
%[text] - Flat ground surface, i.e., 0 inclination angle.
%[text] - Speed reference is 0. \
%[text] Parameters for the Road Grade Profile block
RoadSurface.HorizontalDistance = simscape.Value([0 1 2], "km");
RoadSurface.GradePercent = [0 0 0];
RoadSurface.LeftElevation = simscape.Value(0, "m");

initial.HorizontalPosition = simscape.Value(0, "m");
%[text] Vehicle speed reference
InputLUT.SpeedReference.Time = simscape.Value([0 1 2], "s");
InputLUT.SpeedReference.Speed = simscape.Value([0 0 0], "m/s");
%%
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "600");

applyToModel(sim_in)
%[text] Run simulation.
sim_out = sim(sim_in);

% The returned table contains signals with the logging names specified in the model.
% Logging names are defined on the signal lines or by Simscape selective logging.
result = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);
%%
%[text] Plot logged signals
varnames = [
"Torque command"
"Controller inputs difference"
"Horizontal position"
"Elevation"
"Road grade"
"Vehicle speed"
"Vehicle force"
"G force"
"Battery charge"
"Battery current"
"Battery voltage"
"Motor current"
"Motor torque"
"Motor angular speed"
"Motor voltage"
];

for k = 1 : numel(varnames) %[output:group:6304c5b2]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=150); %[output:364abf83] %[output:8caa02f8] %[output:70e89d8d] %[output:38915d27] %[output:36eedc6d] %[output:1be4c0f7] %[output:84c8adfb] %[output:5a5b10ec] %[output:8ed88fb7] %[output:719a8222] %[output:7e2f1dde] %[output:62e3dfc9] %[output:35511914] %[output:06fe9470] %[output:23538ae3]
end  % for %[output:group:6304c5b2]
%%
%[text] Powers in individual components
function vec = getSimscapeValueVector(tt, name)
logical_index = tt.Properties.VariableNames == name;
unit_text = string(tt.Properties.VariableUnits(logical_index));
vec = simscape.Value(tt.(name), unit_text);
end  % local function
%[text] 
V_vehicle = getSimscapeValueVector(result, "Vehicle speed");
F_vehicle = getSimscapeValueVector(result, "Vehicle force");
P_vehicle = convert(V_vehicle .* F_vehicle, "kW");
VehiclePowerTable = timetable(result.Time, P_vehicle, VariableNames="Vehicle power");
%[text] 
w_motor = getSimscapeValueVector(result, "Motor angular speed");
trq_motor = getSimscapeValueVector(result, "Motor torque");
P_motor = convert(w_motor .* trq_motor, "kW");
MotorPowerTable = timetable(result.Time, P_motor, VariableNames="Motor power");
%[text] 
i_battery = getSimscapeValueVector(result, "Battery current");
v_battery = getSimscapeValueVector(result, "Battery voltage");
P_battery = convert(i_battery .* v_battery, "kW");
BatteryPowerTable = timetable(result.Time, P_battery, VariableNames="Battery power");
%[text] 
bevutil1.SignalUtil.plotTimedData(TimedData=VehiclePowerTable, SignalName="Vehicle power", FigureHeight=150); %[output:928c2518]
bevutil1.SignalUtil.plotTimedData(TimedData=MotorPowerTable, SignalName="Motor power", FigureHeight=150); %[output:8754a372]
bevutil1.SignalUtil.plotTimedData(TimedData=BatteryPowerTable, SignalName="Battery power", FigureHeight=150); %[output:833b8821]
